const app = document.querySelector('#app');
const form = document.querySelector('#create-form');
const input = document.querySelector('#project-name');
const error = document.querySelector('#error');
const list = document.querySelector('#project-list');
const projectFilter = document.querySelector('#project-filter');
const detail = document.querySelector('#project-detail');

async function projects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Unable to load projects');
  return response.json();
}

function showList() {
  document.title = 'Workboard';
  app.querySelector('h1').hidden = false;
  form.hidden = false;
  projectFilter.hidden = false;
  list.hidden = false;
  detail.hidden = true;
}

async function renderList() {
  showList();
  const items = await projects();
  list.replaceChildren();
  for (const project of items) {
    if (Boolean(project.archived) !== (projectFilter.value === 'Archived')) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const stateButton = document.createElement('button');
    stateButton.type = 'button';
    stateButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    stateButton.addEventListener('click', async () => {
      const response = await fetch(`/api/projects/${project.id}/archive`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
      if (response.ok) await renderList();
    });
    row.append(name, summary, button, stateButton);
    list.append(row);
  }
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) return renderList();
  const items = await projects();
  const project = items.find(item => String(item.id) === match[1]);
  if (!project) return renderList();
  document.title = `${project.name} — Workboard`;
  app.querySelector('h1').hidden = true;
  form.hidden = true;
  projectFilter.hidden = true;
  list.hidden = true;
  detail.hidden = false;
  detail.replaceChildren();
  const heading = document.createElement('h1');
  heading.textContent = project.name;
  const back = document.createElement('button');
  back.type = 'button';
  back.textContent = 'Projects';
  back.addEventListener('click', () => { location.href = '/'; });
  detail.append(heading, back);
  const renameForm = document.createElement('form');
  renameForm.className = 'task-form';
  const renameLabel = document.createElement('label');
  renameLabel.htmlFor = 'new-project-name';
  renameLabel.textContent = 'New project name';
  const renameControls = document.createElement('div');
  renameControls.className = 'form-row';
  const renameInput = document.createElement('input');
  renameInput.id = 'new-project-name';
  renameInput.type = 'text';
  renameInput.autocomplete = 'off';
  renameInput.disabled = Boolean(project.archived);
  const renameButton = document.createElement('button');
  renameButton.type = 'submit';
  renameButton.textContent = 'Rename project';
  renameButton.disabled = Boolean(project.archived);
  renameControls.append(renameInput, renameButton);
  const renameError = document.createElement('p');
  renameError.setAttribute('role', 'alert');
  renameError.hidden = true;
  renameForm.append(renameLabel, renameControls, renameError);
  renameForm.addEventListener('submit', async event => {
    event.preventDefault();
    renameError.hidden = true;
    const name = renameInput.value.trim();
    if (!name) { renameError.textContent = 'Project name is required'; renameError.hidden = false; return; }
    const response = await fetch(`/api/projects/${project.id}/rename`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (!response.ok) {
      const result = await response.json();
      renameError.textContent = result.error || 'Unable to rename project';
      renameError.hidden = false;
      return;
    }
    await renderRoute();
  });
  detail.append(renameForm);
  if (project.archived) {
    const archivedNotice = document.createElement('p');
    archivedNotice.textContent = 'Archived project';
    detail.append(archivedNotice);
  }

  const taskForm = document.createElement('form');
  taskForm.className = 'task-form';
  const taskLabel = document.createElement('label');
  taskLabel.htmlFor = 'task-title';
  taskLabel.textContent = 'Task title';
  const taskControls = document.createElement('div');
  taskControls.className = 'form-row';
  const taskInput = document.createElement('input');
  taskInput.id = 'task-title';
  taskInput.type = 'text';
  taskInput.autocomplete = 'off';
  const taskSubmit = document.createElement('button');
  taskSubmit.type = 'submit';
  taskSubmit.textContent = 'Create task';
  taskSubmit.disabled = Boolean(project.archived);
  taskControls.append(taskInput, taskSubmit);
  const taskError = document.createElement('p');
  taskError.setAttribute('role', 'alert');
  taskError.hidden = true;
  taskForm.append(taskLabel, taskControls, taskError);

  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'task-filter';
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    filter.append(option);
  }
  const taskList = document.createElement('section');
  taskList.setAttribute('aria-label', 'Tasks');
  detail.append(taskForm, filterLabel, filter, taskList);

  async function renderTasks() {
    const response = await fetch(`/api/projects/${project.id}/tasks`);
    if (!response.ok) throw new Error('Unable to load tasks');
    const tasks = await response.json();
    taskList.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = Boolean(task.completed);
      checkbox.disabled = Boolean(project.archived);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        const result = await fetch(`/api/projects/${project.id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        if (!result.ok) { checkbox.checked = !checkbox.checked; return; }
        await renderTasks();
      });
      row.append(title, checkbox);
      taskList.append(row);
    }
  }
  filter.addEventListener('change', () => renderTasks().catch(() => {}));
  taskForm.addEventListener('submit', async event => {
    event.preventDefault();
    taskError.hidden = true;
    const title = taskInput.value.trim();
    if (!title) { taskError.textContent = 'Task title is required'; taskError.hidden = false; return; }
    const response = await fetch(`/api/projects/${project.id}/tasks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
    });
    if (!response.ok) {
      const result = await response.json();
      taskError.textContent = result.error || 'Unable to create task';
      taskError.hidden = false;
      return;
    }
    taskInput.value = '';
    await renderTasks();
  });
  await renderTasks();
}

projectFilter.addEventListener('change', () => renderList().catch(() => {}));

form.addEventListener('submit', async event => {
  event.preventDefault();
  error.hidden = true;
  const name = input.value.trim();
  if (!name) {
    error.textContent = 'Project name is required';
    error.hidden = false;
    return;
  }
  const response = await fetch('/api/projects', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to create project';
    error.hidden = false;
    return;
  }
  input.value = '';
  await renderList();
});

renderRoute().catch(error => {
  const message = document.createElement('p');
  message.setAttribute('role', 'alert');
  message.textContent = error.message;
  app.append(message);
});

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || path.join(root, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id GROUP BY p.id ORDER BY p.id`);
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const findProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const findTask = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = (status, type, body) => {
    res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
    res.end(body);
  };
  if (req.method === 'GET' && url.pathname === '/health') {
    return send(200, 'application/json; charset=utf-8', JSON.stringify({ status: 'ok' }));
  }
  const projectRenameRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (projectRenameRoute && req.method === 'PATCH') {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const payload = JSON.parse(body || '{}');
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project name is required' }));
      const id = Number(projectRenameRoute[1]);
      const project = findProject.get(id);
      if (!project) return send(404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
      if (project.archived) return send(403, 'application/json; charset=utf-8', JSON.stringify({ error: 'Archived project' }));
      renameProject.run(name, id);
      return send(200, 'application/json; charset=utf-8', JSON.stringify(findProject.get(id)));
    } catch { return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' })); }
  }
  const projectStateRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (projectStateRoute && req.method === 'PATCH') {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const payload = JSON.parse(body || '{}');
      if (typeof payload.archived !== 'boolean') return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid archive state' }));
      const id = Number(projectStateRoute[1]);
      if (!findProject.get(id)) return send(404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
      setArchived.run(payload.archived ? 1 : 0, id);
      return send(200, 'application/json; charset=utf-8', JSON.stringify(findProject.get(id)));
    } catch { return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' })); }
  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!findProject.get(projectId)) return send(404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
    if (!taskRoute[2] && req.method === 'GET') return send(200, 'application/json; charset=utf-8', JSON.stringify(listTasks.all(projectId)));
    if (!taskRoute[2] && req.method === 'POST') {
      if (findProject.get(projectId).archived) return send(403, 'application/json; charset=utf-8', JSON.stringify({ error: 'Archived project' }));
      try {
        let body = '';
        for await (const chunk of req) body += chunk;
        const payload = JSON.parse(body || '{}');
        const title = typeof payload.title === 'string' ? payload.title.trim() : '';
        if (!title) return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Task title is required' }));
        const result = createTask.run(projectId, title);
        return send(201, 'application/json; charset=utf-8', JSON.stringify(findTask.get(result.lastInsertRowid, projectId)));
      } catch {
        return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
      }
    }
    if (taskRoute[2] && req.method === 'PATCH') {
      if (findProject.get(projectId).archived) return send(403, 'application/json; charset=utf-8', JSON.stringify({ error: 'Archived project' }));
      try {
        let body = '';
        for await (const chunk of req) body += chunk;
        const payload = JSON.parse(body || '{}');
        if (typeof payload.completed !== 'boolean') return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid completion state' }));
        updateTask.run(payload.completed ? 1 : 0, Number(taskRoute[2]), projectId);
        const task = findTask.get(Number(taskRoute[2]), projectId);
        if (!task) return send(404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Task not found' }));
        return send(200, 'application/json; charset=utf-8', JSON.stringify(task));
      } catch {
        return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
      }
    }
    return send(405, 'application/json; charset=utf-8', JSON.stringify({ error: 'Method not allowed' }));
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return send(200, 'application/json; charset=utf-8', JSON.stringify(listProjects.all()));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const payload = JSON.parse(body || '{}');
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project name is required' }));
      const result = createProject.run(name);
      return send(201, 'application/json; charset=utf-8', JSON.stringify(findProject.get(result.lastInsertRowid)));
    } catch {
      return send(400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
  }
  if (req.method === 'GET' && (url.pathname === '/' || url.pathname.startsWith('/projects/'))) {
    try {
      return send(200, 'text/html; charset=utf-8', await readFile(path.join(root, 'index.html')));
    } catch {
      return send(500, 'text/plain; charset=utf-8', 'Unable to load application');
    }
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    return send(200, 'text/javascript; charset=utf-8', await readFile(path.join(root, 'app.js')));
  }
  if (req.method === 'GET' && url.pathname === '/style.css') {
    return send(200, 'text/css; charset=utf-8', await readFile(path.join(root, 'style.css')));
  }
  send(404, 'text/plain; charset=utf-8', 'Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

